package dev.asad.bookshelf;
import jakarta.persistence.*;import jakarta.validation.constraints.*;import java.time.LocalDate;
@Entity public class Entry{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@NotBlank @Size(max=100)private String title;@Size(max=500)private String description="";@NotBlank @Size(max=60)private String category="General";@NotBlank @Size(max=60)private String owner="Me";@NotBlank @Size(max=60)private String value="—";private LocalDate dueDate;@NotBlank @Size(max=40)private String status="Planned";public Long getId(){return id;}public void setId(Long x){id=x;}public String getTitle(){return title;}public void setTitle(String x){title=x;}public String getDescription(){return description;}public void setDescription(String x){description=x;}public String getCategory(){return category;}public void setCategory(String x){category=x;}public String getOwner(){return owner;}public void setOwner(String x){owner=x;}public String getValue(){return value;}public void setValue(String x){value=x;}public LocalDate getDueDate(){return dueDate;}public void setDueDate(LocalDate x){dueDate=x;}public String getStatus(){return status;}public void setStatus(String x){status=x;}}
